// Search box and category filters for the plugin catalog (docs/plugins.md,
// generated by scripts/generate_plugins_page.py), plus anonymous usage counts
// on the catalog cards and plugin pages. The controls start hidden, so without
// JavaScript the page is a plain list of every plugin.
//
// Material's instant navigation swaps pages without a reload, so this runs on
// each page change through `document$`, and also once the DOM is ready in case
// that observable isn't available.

(function () {
  function setUp() {
    const filters = document.querySelector(".plugin-filters");
    const catalog = document.querySelector(".plugin-catalog");
    if (!filters || !catalog || filters.dataset.ready) return;
    filters.dataset.ready = "true";

    const search = filters.querySelector(".plugin-search");
    const buttons = Array.from(filters.querySelectorAll("[data-category]"));
    const count = filters.querySelector(".plugin-count");
    // Each card is a list item; its categories are the <code> tags in it.
    const list = catalog.querySelector(":scope > ul");
    const cards = Array.from(list.children).map((card, index) => ({
      element: card,
      // The generated order is alphabetical; sorting by usage keeps it for ties.
      index,
      folder: folderOf(card.querySelector('a[href$="/plugin.json"]')),
      text: card.textContent.toLowerCase(),
      categories: new Set(
        Array.from(card.querySelectorAll("code"), (tag) => tag.textContent),
      ),
    }));
    const sort = filters.querySelector(".plugin-sort-select");
    const selected = new Set();

    function apply() {
      const words = search.value.toLowerCase().split(/\s+/).filter(Boolean);
      let shown = 0;
      for (const card of cards) {
        const matchesText = words.every((word) => card.text.includes(word));
        // A card matches when it has any selected category.
        const matchesCategory =
          selected.size === 0 ||
          [...selected].some((c) => card.categories.has(c));
        const visible = matchesText && matchesCategory;
        // An inline style wins over any theme rule for the card's display,
        // in every browser; the attribute keeps it hidden from assistive tech.
        card.element.style.display = visible ? "" : "none";
        card.element.hidden = !visible;
        if (visible) shown += 1;
      }
      count.textContent =
        shown === cards.length
          ? `${cards.length} plugins`
          : `${shown} of ${cards.length} plugins`;
    }

    // "input" covers typing and pasting; "search" covers the clear button some
    // browsers draw in a search box; "keyup" is a fallback for the rest.
    for (const event of ["input", "search", "keyup"]) {
      search.addEventListener(event, apply);
    }
    // Sort by name (the generated order) or by usage from stats.json. The
    // usage options stay disabled until the stats have loaded.
    let usage = {};
    function reorder() {
      const metric = sort.value;
      const score = (card) => {
        const plugin = usage[card.folder];
        if (!plugin || metric === "name") return 0;
        return metric === "launches" ? plugin.launches : usersOf(plugin);
      };
      const ordered = [...cards].sort(
        (a, b) => score(b) - score(a) || a.index - b.index,
      );
      list.append(...ordered.map((card) => card.element));
    }
    sort.addEventListener("change", reorder);
    loadStats().then((data) => {
      if (!data || !data.plugins) return;
      usage = data.plugins;
      for (const option of sort.options) option.disabled = false;
    });

    for (const button of buttons) {
      button.addEventListener("click", () => {
        const category = button.dataset.category;
        if (selected.has(category)) selected.delete(category);
        else selected.add(category);
        button.setAttribute("aria-pressed", String(selected.has(category)));
        apply();
      });
    }
    filters.hidden = false;
    apply();
  }

  // Usage counts from plugins/stats.json (served by the registry's Worker),
  // fetched once per visit. Without data nothing is shown.
  let stats;
  function loadStats() {
    // Revalidate: the zone's browser cache TTL can outlast the hourly counts.
    stats ??= fetch("/plugins/stats.json", { cache: "no-cache" })
      .then((response) => (response.ok ? response.json() : null))
      .catch(() => null)
      .then((data) => {
        // Don't remember a failure: the next page tries again.
        if (!data) stats = undefined;
        return data;
      });
    return stats;
  }

  // The steadier number: the last complete week, or the week so far early on.
  function usersOf(usage) {
    return usage.usersLastWeek > 0 ? usage.usersLastWeek : usage.usersThisWeek;
  }

  // The plugins/<dir>/ folder of a manifest link, which stats.json is keyed by.
  function folderOf(link) {
    return link
      ? /\/plugins\/([^/]+)\/plugin\.json$/.exec(link.href)?.[1]
      : undefined;
  }

  function usersText(usage) {
    const count = usersOf(usage);
    if (count === 0) return null;
    const period = usage.usersLastWeek > 0 ? "last week" : "this week";
    return `${count.toLocaleString()} ${count === 1 ? "user" : "users"} ${period}`;
  }

  async function showUsage() {
    // Plugins are matched by the plugins/<dir>/ folder of their manifest link.
    // Claim the links before awaiting, so a second call (document$ and the
    // DOM-ready fallback can both fire) doesn't add the same usage twice.
    const links = Array.from(
      document.querySelectorAll('.md-content a[href$="/plugin.json"]'),
    ).filter((link) => !link.dataset.usage);
    for (const link of links) link.dataset.usage = "true";
    if (links.length === 0) return;
    const data = await loadStats();
    if (!data || !data.plugins) return;
    for (const link of links) {
      const folder = folderOf(link);
      const usage = folder && data.plugins[folder];
      if (!usage) continue;
      const card = link.closest(".plugin-catalog > ul > li");
      if (card) {
        const text = usersText(usage);
        if (!text) continue;
        const line = document.createElement("p");
        line.className = "plugin-usage";
        line.textContent = text;
        link.closest("p")?.before(line);
        continue;
      }
      // A plugin page: add a row to its details list.
      const row = link.closest("li");
      if (!row) continue;
      const item = document.createElement("li");
      const label = document.createElement("strong");
      label.textContent = "Usage:";
      const users = usersText(usage) ?? "no users yet";
      const since = data.since ? ` since ${data.since}` : "";
      item.append(
        label,
        ` ${users} · ${usage.launches.toLocaleString()} launches${since}`,
      );
      row.after(item);
    }
  }

  function onPage() {
    setUp();
    showUsage();
  }

  if (typeof document$ !== "undefined") {
    document$.subscribe(onPage);
  }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", onPage);
  } else {
    onPage();
  }
})();
